var e=(e,t,n,r,i,a,o)=>({id:e,when:{slot:n,option:r},with:{slot:i,option:a},type:t,note:o}),t=[e(`lsm-bloom`,`synergy`,`index-structure`,`lsm`,`secondary-index`,`bloom`,`An LSM point lookup may probe every sorted run; a per-SSTable Bloom filter (~10 bits/key, ~1% false positives) rejects most runs without I/O, cutting read amplification from O(levels) to about 1 data-block read.`),e(`lsm-lsmkv`,`synergy`,`index-structure`,`lsm`,`table-organization`,`lsm-kv`,`Treating a table as a sorted key space is exactly what an LSM stores; key-prefix = table/partition, so range scans and TTL/tombstones map naturally onto SSTables.`),e(`lsm-versioned-keys`,`synergy`,`index-structure`,`lsm`,`mvcc-storage`,`time-travel`,`Appending the commit timestamp to the key keeps every version as a separate sorted entry; compaction garbage-collects versions older than the retention horizon (Bigtable/Cockroach Pebble).`),e(`lsm-lz4zstd`,`synergy`,`index-structure`,`lsm`,`compression`,`lz4-zstd`,`Immutable, sorted, block-structured SSTables compress very well; RocksDB-style stores use LZ4 on upper levels and ZSTD on the bottom level where most data sits.`),e(`lsm-aries-conflict`,`conflict`,`index-structure`,`lsm`,`recovery`,`aries-steal-noforce`,`LSM has no in-place page updates, so ARIES page-LSN redo and CLR undo do not map; recovery is instead "replay the memtable WAL" because SSTables are immutable.`),e(`lsm-bufferpool`,`conflict`,`index-structure`,`lsm`,`page-cache`,`buffer-pool`,`A page-oriented buffer pool with steal/no-force semantics is a poor fit: LSM reads are served by a block cache of immutable blocks, not dirty-tracked pages.`),e(`bplus-buffer-pool`,`synergy`,`index-structure`,`bplustree`,`page-cache`,`buffer-pool`,`In-place B+tree updates need explicit pin/dirty tracking and eviction control so inner pages stay hot and WAL ordering is enforced.`),e(`bplus-aries`,`synergy`,`index-structure`,`bplustree`,`recovery`,`aries-steal-noforce`,`ARIES physiological logging (page + logical operation inside the page) was designed for in-place page updates such as B+tree leaf inserts and splits.`),e(`bplus-nsm`,`synergy`,`index-structure`,`bplustree`,`page-layout`,`nsm-row`,`Leaf pages of a B+tree are slotted row pages; whole-row access per page is exactly what OLTP seeks.`),e(`bplus-heap-ok`,`synergy`,`table-organization`,`index-organized`,`index-structure`,`bplustree`,`A clustered (index-organized) table IS a B+tree whose leaves hold the rows, giving PK range scans with no heap fetches.`),e(`iot-secondary-pk`,`implies`,`table-organization`,`index-organized`,`secondary-index`,`btree`,`Secondary indexes in a clustered table store the primary key and need a second descent; wide PKs bloat every secondary index, so a B+tree secondary is the default.`),e(`heap-hash-secondary`,`synergy`,`table-organization`,`heap`,`secondary-index`,`btree`,`Heap tables decouple index entries from rows via TIDs so any number of B+tree indexes work symmetrically; HOT updates avoid touching them when no indexed column changes.`),e(`heap-appendonly-mvcc`,`synergy`,`table-organization`,`heap`,`mvcc-storage`,`append-only`,`Append-only versions are just extra tuples in the heap; this is why PostgreSQL needs VACUUM and why its dead tuples bloat tables and indexes.`),e(`iot-undo-mvcc`,`synergy`,`table-organization`,`index-organized`,`mvcc-storage`,`delta-undo`,`Keeping only the newest version in the clustered tree and old versions in an undo log keeps the tree compact (InnoDB).`),e(`cow-no-wal`,`implies`,`index-structure`,`cow-btree`,`recovery`,`shadow-cow`,`Never overwriting a published page means a crash simply leaves the old root valid, so shadow paging replaces WAL-based redo/undo.`),e(`cow-mmap`,`synergy`,`index-structure`,`cow-btree`,`page-cache`,`mmap`,`Published pages are immutable, so the OS page cache can serve them via mmap without WAL-ordering hazards (LMDB).`),e(`cow-write-concurrency`,`conflict`,`index-structure`,`cow-btree`,`concurrency-control`,`2pl`,`COW trees usually have a single writer and cheap snapshots for readers; fine-grained 2PL adds complexity that the design avoids by serialising writers.`),e(`bwtree-mvcc`,`synergy`,`index-structure`,`bwtree`,`concurrency-control`,`mvcc-timestamp`,`Latch-free delta records fit naturally with versioned data and epoch-based reclamation; Hekaton pairs a Bw-tree with optimistic MVCC.`),e(`art-memory`,`implies`,`index-structure`,`art`,`page-cache`,`buffer-pool`,`ART is pointer-based and shines in memory; on a disk-based system you need a buffer manager variant that supports pointer swizzling (LeanStore/Umbra) or the index must be fully memory resident.`),e(`art-compiled`,`synergy`,`index-structure`,`art`,`exec-model`,`compiled`,`Both target main-memory CPU efficiency (HyPer/Umbra): ART lookups and compiled pipelines avoid interpretation and cache misses.`),e(`hash-range-conflict`,`conflict`,`index-structure`,`hash`,`sharding`,`range`,`A hash index/placement destroys key order, so range predicates and range-based shard routing cannot use it; use ordered structures for range-sharded data.`),e(`columnar-vectorized`,`implies`,`table-organization`,`columnar`,`exec-model`,`vectorized`,`Columnar chunks are arrays; tuple-at-a-time Volcano wastes that layout, so vectorized (or compiled) execution is the natural pairing.`),e(`columnar-dsm`,`implies`,`table-organization`,`columnar`,`page-layout`,`dsm-column`,`A columnar table needs a column-oriented physical layout (pure DSM or PAX row groups).`),e(`columnar-compress`,`synergy`,`table-organization`,`columnar`,`compression`,`dictionary`,`Homogeneous column data compresses 5-20x with dictionary/RLE/bit-packing, and predicates evaluate directly on codes.`),e(`columnar-zonemap`,`synergy`,`table-organization`,`columnar`,`secondary-index`,`zonemap-minmax`,`Immutable column chunks carry min/max metadata for free; zone maps skip entire row groups when data is clustered on the filter column.`),e(`columnar-oltp-btree`,`conflict`,`table-organization`,`columnar`,`secondary-index`,`btree`,`Row-granular B+tree secondary indexes on a columnar table lead to point lookups that reassemble tuples from many column files; use zone maps/bitmaps and sort order instead.`),e(`columnar-aries`,`conflict`,`table-organization`,`columnar`,`recovery`,`aries-steal-noforce`,`Fine-grained ARIES page-level logging is a poor match for bulk-loaded immutable column segments; analytic stores commit whole parts/segments and atomically swap metadata.`),e(`columnar-disagg`,`synergy`,`table-organization`,`columnar`,`storage-architecture`,`disaggregated-object-store`,`Large immutable columnar files with min/max metadata are ideal for object stores: only needed columns/chunks are fetched with range GETs (Snowflake, BigQuery, Parquet).`),e(`rle-sorted`,`synergy`,`compression`,`rle`,`table-organization`,`columnar`,`RLE needs sorted or clustered values; a columnar table sorted on its key yields long runs and operators can compute on runs without decompressing.`),e(`pax-parquet-compress`,`synergy`,`page-layout`,`pax`,`compression`,`dictionary`,`Each PAX minipage / Parquet column chunk has a local dictionary, giving columnar compression while keeping row groups as the I/O unit.`),e(`dsm-oltp-conflict`,`conflict`,`page-layout`,`dsm-column`,`concurrency-control`,`2pl`,`Row-level locking on pure column storage means one logical row touches many pages; analytic columnar stores prefer snapshot/batch concurrency instead.`),e(`nsm-volcano`,`synergy`,`page-layout`,`nsm-row`,`exec-model`,`volcano`,`Row pages produce whole tuples, which a tuple-at-a-time iterator consumes directly with no re-assembly.`),e(`delta-sorted`,`synergy`,`compression`,`delta`,`index-structure`,`lsm`,`Sorted, immutable runs have small deltas between neighbouring keys (prefix/delta encoding of keys and timestamps in SSTables).`),e(`compiled-push`,`synergy`,`exec-model`,`compiled`,`data-direction`,`push`,`Data-centric code generation compiles pipelines push-style (produce/consume), keeping tuples in registers until a pipeline breaker.`),e(`volcano-pull`,`synergy`,`exec-model`,`volcano`,`data-direction`,`pull`,`The iterator model is by definition pull-based via next(); lazy evaluation gives cheap LIMIT early-out.`),e(`push-morsel`,`synergy`,`data-direction`,`push`,`scheduling`,`morsel-driven`,`Push-style pipelines give the scheduler independent pipeline tasks and clear breakers where workers synchronise, which is what morsel-driven parallelism needs.`),e(`morsel-intra-op`,`implies`,`scheduling`,`morsel-driven`,`parallelism`,`intra-operator`,`Morsels split each scan/operator across all cores, i.e. intra-operator parallelism with thread-local state and a global merge.`),e(`compiled-jit`,`implies`,`exec-model`,`compiled`,`code-execution`,`codegen-jit`,`Compiled execution by definition needs runtime code generation (LLVM/Janino) or a hybrid thereof.`),e(`compiled-compile-latency`,`conflict`,`code-execution`,`codegen-jit`,`plan-cache`,`none`,`Without a plan cache every query pays 10s-100s ms of LLVM compile time; pure JIT needs caching or an adaptive interpreter fallback.`),e(`hybrid-adaptive-umbra`,`synergy`,`code-execution`,`hybrid-adaptive`,`scheduling`,`morsel-driven`,`Morsel boundaries are safe points to switch a running pipeline from interpreted bytecode to compiled machine code (Umbra adaptive execution).`),e(`vectorized-primitives`,`synergy`,`exec-model`,`vectorized`,`code-execution`,`precompiled-primitives`,`Vectorized engines amortise interpretation per vector, so ahead-of-time compiled primitives are enough and avoid any runtime compile latency.`),e(`materialization-exchange`,`synergy`,`exec-model`,`materialization`,`parallelism`,`intra-query-exchange`,`Stage-wise materialised outputs are natural shuffle boundaries and fault-tolerance checkpoints (MapReduce/Spark).`),e(`thread-per-core-shardnothing`,`synergy`,`scheduling`,`thread-per-core`,`storage-architecture`,`shared-nothing`,`Per-core ownership of a data shard extends naturally to per-node ownership; Scylla/Seastar apply shared-nothing inside the machine as well as across them.`),e(`thread-per-core-uring`,`synergy`,`scheduling`,`thread-per-core`,`page-cache`,`direct-io-uring`,`One run-loop per core submits async I/O via its own io_uring ring without cross-thread locking (TigerBeetle, Scylla).`),e(`thread-per-conn-mmap`,`conflict`,`scheduling`,`thread-per-connection`,`page-cache`,`mmap`,`Page faults block the whole backend thread; with many connections the OS-driven stalls and TLB shootdowns amplify under contention.`),e(`thread-per-conn-2pl`,`synergy`,`scheduling`,`thread-per-connection`,`concurrency-control`,`2pl`,`A blocked lock waiter just parks its dedicated thread; blocking-style 2PL maps one-to-one to blocking sessions.`),e(`cascades-exchange`,`synergy`,`optimizer-search`,`top-down-cascades`,`parallelism`,`intra-query-exchange`,`Cascades models distribution as a required physical property; enforcer rules insert hash/broadcast exchanges only where the child does not already satisfy it.`),e(`dphyp-sampling`,`synergy`,`optimizer-search`,`hypergraph-dphyp`,`statistics`,`sampling`,`DPhyp enumerates many bushy plans; join-crossing sampling gives it correlation-aware cardinalities where histograms assume independence.`),e(`dp-histogram`,`synergy`,`optimizer-search`,`bottom-up-dp`,`statistics`,`equi-depth-histogram`,`System R-style DP plus histograms/MCV lists is the classical combination used by PostgreSQL and MySQL.`),e(`heuristic-nostats`,`conflict`,`optimizer-search`,`heuristic-rules`,`statistics`,`equi-width-histogram`,`A rule-based optimizer cannot exploit statistics; investing in histograms yields no plan-quality benefit without a cost model.`),e(`learned-feedback`,`implies`,`optimizer-search`,`learned`,`plan-cache`,`normalized-literals`,`Learned optimizers need to recognise repeated query shapes and store execution feedback; normalised statement fingerprints serve as the key.`),e(`hll-ndv-join`,`synergy`,`statistics`,`hyperloglog-ndv`,`optimizer-search`,`top-down-cascades`,`Mergeable NDV sketches per partition give group-by and join output estimates in distributed optimizers (e.g. StarRocks).`),e(`ddsketch-merge`,`synergy`,`statistics`,`ddsketch-quantile`,`storage-architecture`,`disaggregated-object-store`,`Mergeable sketches can be computed per micro-partition in parallel and combined, matching immutable files without a global ANALYZE pass.`),e(`prepared-pooler-conflict`,`conflict`,`plan-cache`,`prepared-stmt`,`scheduling`,`thread-pool`,`Session-scoped prepared statements break when a transaction-mode pooler or request-level worker reassigns the session; the plan cache must be global or statements re-prepared.`),e(`nocache-codegen-conflict`,`conflict`,`exec-model`,`compiled`,`plan-cache`,`none`,`Compile cost is paid on every run if compiled code is not cached; pair compiled execution with a normalised plan cache or an interpreter warm-up.`),e(`mvcc-snapshot`,`synergy`,`concurrency-control`,`mvcc-timestamp`,`isolation-default`,`snapshot`,`Timestamped versions directly give snapshot reads: each transaction reads as-of its start timestamp without blocking writers.`),e(`ssi-serializable`,`implies`,`concurrency-control`,`mvcc-ssi`,`isolation-default`,`serializable`,`SSI exists to give serializable behaviour on top of snapshot isolation by detecting dangerous rw-antidependency structures.`),e(`2pl-deadlock`,`implies`,`concurrency-control`,`2pl`,`deadlock-handling`,`wait-for-graph`,`Blocking locks create circular waits; 2PL needs detection (wait-for graph), timeouts, or prevention (wait-die/wound-wait).`),e(`mvcc-deadlock-fewer`,`synergy`,`concurrency-control`,`mvcc-timestamp`,`deadlock-handling`,`timeout`,`With MVCC only writers block writers, so deadlocks are rare and a simple timeout or row-lock graph search is enough.`),e(`calvin-no-2pc`,`conflict`,`concurrency-control`,`deterministic-calvin`,`distributed-commit`,`two-phase-commit`,`Deterministic execution agrees on order before running, so participants never vote; layering 2PC on top duplicates coordination and adds needless round trips.`),e(`calvin-implies-commit`,`implies`,`concurrency-control`,`deterministic-calvin`,`distributed-commit`,`calvin-deterministic`,`Calvin replaces atomic-commit protocols with agreement on input order.`),e(`calvin-command-log`,`synergy`,`concurrency-control`,`deterministic-calvin`,`recovery`,`command-logging`,`If execution is deterministic, logging the ordered inputs is sufficient for both recovery and replication.`),e(`calvin-ordered-locks`,`synergy`,`concurrency-control`,`deterministic-calvin`,`deadlock-handling`,`ordered-acquire`,`Locks are requested in the agreed log order by a single scheduler thread, so deadlock is impossible by construction.`),e(`occ-contention-conflict`,`conflict`,`concurrency-control`,`occ`,`isolation-default`,`serializable`,`Under high contention, OCC validation aborts spike and wasted work grows; add retries/backoff or switch to pessimistic locking for hot rows.`),e(`undo-aries`,`synergy`,`mvcc-storage`,`delta-undo`,`recovery`,`aries-steal-noforce`,`The undo log serves rollback, crash undo of loser transactions, and MVCC old-version reconstruction, all driven by ARIES.`),e(`appendonly-vacuum-bloat`,`conflict`,`mvcc-storage`,`append-only`,`index-structure`,`bplustree`,`New versions require new index entries in every B+tree unless HOT applies, so update-heavy workloads bloat indexes and need aggressive VACUUM.`),e(`timetravel-disagg`,`synergy`,`mvcc-storage`,`time-travel`,`storage-architecture`,`disaggregated-object-store`,`Immutable files in object storage make retention of old snapshots a metadata operation (Snowflake time travel, zero-copy clones).`),e(`truetime-spanner-2pc`,`synergy`,`clock`,`truetime`,`distributed-commit`,`two-phase-commit`,`2PC chooses a commit timestamp at the coordinator and waits out the TrueTime uncertainty, yielding external consistency across Paxos groups.`),e(`hlc-raft`,`synergy`,`clock`,`hlc`,`consensus`,`raft`,`Per-range Raft groups plus HLC timestamps give MVCC without special hardware (CockroachDB), at the cost of uncertainty-interval read restarts.`),e(`oracle-percolator`,`synergy`,`clock`,`timestamp-oracle`,`distributed-commit`,`percolator-timestamp`,`Percolator-style transactions require a strictly increasing timestamp service for start and commit timestamps.`),e(`lamport-snapshot-conflict`,`conflict`,`clock`,`lamport`,`distributed-commit`,`percolator-timestamp`,`Snapshot reads need timestamps comparable with wall-clock or a global counter; plain Lamport clocks cannot define a consistent global snapshot.`),e(`vectorclock-quorum`,`synergy`,`clock`,`vector-clock`,`replication`,`async`,`Leaderless asynchronous replicas can accept conflicting writes; vector clocks detect concurrent versions for later reconciliation (Dynamo).`),e(`raft-quorum`,`implies`,`consensus`,`raft`,`replication`,`quorum-raft`,`Choosing Raft means replication is majority-quorum with a leader-ordered log.`),e(`paxos-quorum`,`implies`,`consensus`,`multi-paxos`,`replication`,`quorum-raft`,`Multi-Paxos is likewise a majority-quorum replicated log with a distinguished leader.`),e(`primary-backup-async`,`synergy`,`consensus`,`none-primary-backup`,`replication`,`async`,`Without consensus, the cheap and common setup is asynchronous or semi-synchronous log shipping with external failover.`),e(`sync-availability-conflict`,`conflict`,`replication`,`sync`,`consensus`,`none-primary-backup`,`Writing to all replicas synchronously with no quorum protocol blocks on any single failure; majority quorums (Raft/Paxos) preserve availability.`),e(`raft-range-sharding`,`synergy`,`consensus`,`raft`,`sharding`,`range`,`Many small Raft groups, one per range, spread leaders across nodes and let ranges split and merge independently (CockroachDB).`),e(`consistent-hash-async`,`synergy`,`sharding`,`consistent-hash`,`replication`,`async`,`Ring placement with N-1 clockwise replicas and tunable consistency suits leaderless asynchronous replication (Cassandra/Dynamo).`),e(`range-shard-2pc`,`implies`,`sharding`,`range`,`distributed-commit`,`two-phase-commit`,`Multi-range transactions need atomic commit across ranges; most range-sharded SQL stores implement a 2PC variant over consensus groups.`),e(`vindex-semisync`,`synergy`,`sharding`,`directory-vindex`,`replication`,`semi-sync`,`Vitess routes to MySQL shards through vindexes and runs semi-sync replicas per shard to limit data loss on failover.`),e(`hash-shard-shuffle`,`synergy`,`sharding`,`hash`,`parallelism`,`intra-query-exchange`,`Joining tables hash-partitioned on the join key is shuffle-free (colocated join); otherwise exchanges must repartition by hash.`),e(`rowlog-cdc`,`synergy`,`replication-log`,`row-binlog`,`sharding`,`directory-vindex`,`Row-based logical logs let a sharding layer (Vitess VReplication) reshard or build lookup vindexes by tailing changes.`),e(`physical-wal-heterogeneous`,`conflict`,`replication-log`,`physical-wal`,`index-structure`,`lsm`,`Physical page-level shipping assumes identical page structure on replicas; LSM replicas diverge in compaction timing, so LSM systems replicate logical writes instead.`),e(`disagg-sharednothing-conflict`,`conflict`,`storage-architecture`,`disaggregated-object-store`,`page-cache`,`mmap`,`Object storage has no byte-addressable mapping; mmap of remote data is not possible, so a managed cache tier is needed.`),e(`disagg-buffer`,`implies`,`storage-architecture`,`disaggregated-object-store`,`page-cache`,`buffer-pool`,`Per-request S3 latency (tens of ms) forces compute nodes to run a local SSD/memory cache tier in front of object storage.`),e(`sharednothing-hash-range`,`synergy`,`storage-architecture`,`shared-nothing`,`sharding`,`range`,`Local ownership of key ranges per node gives locality and enables per-range replication.`),e(`lsm-compaction-disagg`,`synergy`,`index-structure`,`lsm`,`storage-architecture`,`disaggregated-object-store`,`Immutable SSTables are ideal objects for S3-style storage and let compaction run on separate stateless compute (e.g. remote compaction).`),e(`io-uring-aries`,`synergy`,`page-cache`,`direct-io-uring`,`recovery`,`aries-steal-noforce`,`Direct I/O gives the DBMS full control over write ordering, which the write-ahead rule requires; io_uring supplies the queue depth to hide fsync latency.`),e(`mmap-aries-conflict`,`conflict`,`page-cache`,`mmap`,`recovery`,`aries-steal-noforce`,`With mmap the OS can flush dirty pages before their WAL records are durable, violating the write-ahead rule that ARIES depends on.`),e(`semisync-2pc`,`synergy`,`replication`,`semi-sync`,`distributed-commit`,`two-phase-commit`,`XA/2PC prepare records replicated to at least one replica prevent in-doubt transactions from being lost on failover.`),e(`single-node-lamport`,`conflict`,`distributed-commit`,`none-single-node`,`consensus`,`multi-paxos`,`Running consensus for a database with no cross-shard commit is overkill unless you need HA replicas of the same node, in which case use primary-backup.`)];export{t as default};